import sqlite3
import hashlib
import os
import unicodedata
import re
from flask import Flask, request, jsonify, g
import bcrypt

app = Flask(__name__)
DATABASE = '/tmp/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        display_name TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        is_admin INTEGER DEFAULT 0,
        email TEXT UNIQUE NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS password_reset_tokens (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        token TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        used INTEGER DEFAULT 0,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

def validate_username(username):
    """Validate username format - allows unicode letters and digits."""
    if not username or len(username) < 3 or len(username) > 30:
        return False
    # Allow unicode word characters but not special symbols
    if not re.match(r'^[\w]+$', username, re.UNICODE):
        return False
    # Block control characters
    for ch in username:
        if unicodedata.category(ch).startswith('C'):
            return False
    return True

def normalize_display_name(name):
    """Normalize display name using NFC for consistent rendering."""
    return unicodedata.normalize('NFC', name.strip())

def check_username_available(db, username):
    """Check if username is already taken.
    We compare against stored usernames directly.
    """
    row = db.execute(
        'SELECT id FROM users WHERE username = ?', (username,)
    ).fetchone()
    return row is None

def sanitize_and_store_username(username):
    """Process username for storage.
    Apply NFKC normalization to collapse compatibility equivalents
    for display purposes, stored as the canonical form."""
    # NFKC normalization collapses characters like \uff41 -> 'a'
    return unicodedata.normalize('NFKC', username)

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')
    email = data.get('email', '')

    if not validate_username(username):
        return jsonify({'error': 'Invalid username format'}), 400

    if len(password) < 8 or len(password) > 128:
        return jsonify({'error': 'Password must be 8-128 characters'}), 400

    if not re.match(r'^[^@]+@[^@]+\.[^@]+$', email):
        return jsonify({'error': 'Invalid email format'}), 400

    db = get_db()

    # Check availability using the raw (validated) username
    if not check_username_available(db, username):
        return jsonify({'error': 'Username already taken'}), 409

    # Now normalize for storage - this is the canonical form
    stored_username = sanitize_and_store_username(username)

    # Hash password with bcrypt
    password_hash = bcrypt.hashpw(
        password.encode('utf-8'), bcrypt.gensalt(rounds=12)
    ).decode('utf-8')

    display_name = normalize_display_name(username)

    try:
        db.execute(
            'INSERT INTO users (username, display_name, password_hash, email) VALUES (?, ?, ?, ?)',
            (stored_username, display_name, password_hash, email.lower())
        )
        db.commit()
        return jsonify({'message': 'Registration successful', 'username': stored_username}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username or email already exists'}), 409

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    # Normalize the login username the same way as storage
    lookup_username = sanitize_and_store_username(username)

    db = get_db()
    row = db.execute(
        'SELECT id, username, password_hash, is_admin FROM users WHERE username = ?',
        (lookup_username,)
    ).fetchone()

    if row is None:
        # Constant-time-ish: still hash to prevent timing
        bcrypt.hashpw(b'dummy', bcrypt.gensalt(rounds=12))
        return jsonify({'error': 'Invalid credentials'}), 401

    if bcrypt.checkpw(password.encode('utf-8'), row['password_hash'].encode('utf-8')):
        token = os.urandom(32).hex()
        return jsonify({
            'token': token,
            'username': row['username'],
            'is_admin': bool(row['is_admin'])
        }), 200

    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/api/user/<username>', methods=['GET'])
def get_user_profile(username):
    lookup = sanitize_and_store_username(username)
    db = get_db()
    row = db.execute(
        'SELECT username, display_name, is_admin FROM users WHERE username = ?',
        (lookup,)
    ).fetchone()
    if row:
        return jsonify(dict(row)), 200
    return jsonify({'error': 'User not found'}), 404

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
